export function dynamicReasoningSwitch(taskDetails) {
  const complexityThreshold = 0.7; // Example threshold
  const urgencyThreshold = 0.5; // Example threshold

  const { complexity, urgency } = taskDetails;

  if (complexity > complexityThreshold || urgency < urgencyThreshold) {
    return 'system2'; // Assign to slow, analytical reasoning
  } else {
    return 'system1'; // Assign to fast, heuristic reasoning
  }
}